//! j8bytecode: j8's bytecode, which is V8's (Ignition) byte for byte: the bytecode list and operand types come from
//! V8's headers (`v8.json`, generated by tools/v8bytecodes.py, turned into Rust by `j8macros::bytecodes!`), operand
//! scaling, register operands and the interpreter frame layout follow V8 (see `v8.rs`). The dependency root: it
//! depends on no other j8 crate.
extern crate alloc;

mod v8;

pub use v8::{Bytecode, BytecodeError, Decoded, Decoder, Encoder, ImplicitRegisterUse, Intrinsic, OperandScale, OperandSize, OperandType, OperandTypeInfo, OperandValue, Register, Runtime};
